insert into public.bible_verses (id, book_key, book_name, chapter, verse, content, sort_order)
values
('dan-9-12','dan','다니엘',9,12,'주께서 큰 재앙을 우리에게 내리사 우리와 및 우리를 재판하던 재판관을 쳐서 하신 말씀을 이루셨사오니 온 천하에 예루살렘에서 일어난 일 같은 것이 없나이다',22001),
('dan-9-13','dan','다니엘',9,13,'모세의 율법에 기록된 대로 이 모든 재앙이 이미 우리에게 내렸사오나 우리는 우리의 죄악을 떠나고 주의 진리를 깨달아 우리 하나님 여호와의 얼굴을 기쁘게 하지 아니하였나이다',22002),
('dan-9-14','dan','다니엘',9,14,'그러므로 여호와께서 이 재앙을 간직하여 두셨다가 우리에게 내리게 하셨사오니 우리의 하나님 여호와께서 행하시는 모든 일이 공의로우시나 우리가 그 목소리를 듣지 아니하였음이니이다',22003),
('dan-9-15','dan','다니엘',9,15,'강한 손으로 주의 백성을 애굽 땅에서 인도하여 내시고 오늘과 같이 명성을 얻으신 우리 주 하나님이여 우리는 범죄하였고 악을 행하였나이다',22004),
('dan-9-16','dan','다니엘',9,16,'주여 구하옵나니 주는 주의 공의를 따라 주의 분노를 주의 성 예루살렘, 주의 거룩한 산에서 떠나게 하옵소서 이는 우리의 죄와 우리 조상들의 죄악으로 말미암아 예루살렘과 주의 백성이 사면에 있는 자들에게 수치를 당함이니이다',22005),
('dan-9-17','dan','다니엘',9,17,'그러하온즉 우리 하나님이여 지금 주의 종의 기도와 간구를 들으시고 주를 위하여 주의 얼굴 빛을 주의 황폐한 성소에 비추시옵소서',22006),
('dan-9-18','dan','다니엘',9,18,'나의 하나님이여 귀를 기울여 들으시며 눈을 떠서 우리의 황폐한 상황과 주의 이름으로 일컫는 성을 보옵소서 우리가 주 앞에 간구하옵는 것은 우리의 공의를 의지하여 하는 것이 아니요 주의 큰 긍휼을 의지하여 함이니이다',22007),
('dan-9-19','dan','다니엘',9,19,'주여 들으소서 주여 용서하소서 주여 귀를 기울이시고 행하소서 지체하지 마옵소서 나의 하나님이여 주 자신을 위하여 하시옵소서 이는 주의 성과 주의 백성이 주의 이름으로 일컫는 바 됨이니이다',22008),
('dan-9-20','dan','다니엘',9,20,'내가 이같이 말하여 기도하며 내 죄와 내 백성 이스라엘의 죄를 자복하고 내 하나님의 거룩한 산을 위하여 내 하나님 여호와 앞에 간구할 때',22009),
('dan-9-21','dan','다니엘',9,21,'곧 내가 기도할 때에 이전에 환상 중에 본 그 사람 가브리엘이 빨리 날아서 저녁 제사를 드릴 때 즈음에 내게 이르더니',22010),
('dan-9-22','dan','다니엘',9,22,'내게 가르치며 내게 말하여 이르되 다니엘아 내가 이제 네게 지혜와 총명을 주려고 왔느니라 하니라',22011),
('dan-9-23','dan','다니엘',9,23,'곧 네가 기도를 시작할 즈음에 명령이 내렸으므로 이제 네게 알리러 왔느니라 너는 크게 은총을 입은 자라 그런즉 너는 이 일을 생각하고 그 환상을 깨달을지니라',22012),
('dan-9-24','dan','다니엘',9,24,'네 백성과 네 거룩한 성을 위하여 일흔 이레를 기한으로 정하였나니 허물이 그치며 죄가 끝나며 죄악이 용서되며 영원한 의가 드러나며 환상과 예언이 응하며 또 지극히 거룩한 이가 기름 부음을 받으리라',22013),
('dan-9-25','dan','다니엘',9,25,'그러므로 너는 깨달아 알지니라 예루살렘을 중건하라는 영이 날 때부터 기름 부음을 받은 자 곧 왕이 일어나기까지 일곱 이레와 예순두 이레가 지날 것이요 그 곤란한 동안에 성이 중건되어 광장과 거리가 세워질 것이며',22014),
('dan-9-26','dan','다니엘',9,26,'예순두 이레 후에 기름 부음을 받은 자가 끊어져 없어질 것이며 장차 한 왕의 백성이 와서 그 성읍과 성소를 무너뜨리려니와 그의 마지막은 홍수에 휩쓸림 같을 것이며 또 끝까지 전쟁이 있으리니 황폐할 것이 작정되었느니라',22015),
('dan-9-27','dan','다니엘',9,27,'그가 장차 많은 사람들과 더불어 한 이레 동안의 언약을 굳게 맺고 그가 그 이레의 절반에 제사와 예물을 금지할 것이며 또 포악하여 가증한 것이 날개를 의지하여 설 것이며 또 이미 정한 종말까지 진노가 황폐하게 하는 자에게 쏟아지리라 하였느니라 하니라',22016),
('dan-10-1','dan','다니엘',10,1,'바사 왕 고레스 제삼년에 한 일이 벨드사살이라 이름한 다니엘에게 나타났는데 그 일이 참되니 곧 큰 전쟁에 관한 것이라 다니엘이 그 일을 분명히 알았고 그 환상을 깨달으니라',22017),
('dan-10-2','dan','다니엘',10,2,'그 때에 나 다니엘이 세 이레 동안을 슬퍼하며',22018),
('dan-10-3','dan','다니엘',10,3,'세 이레가 차기까지 좋은 떡을 먹지 아니하며 고기와 포도주를 입에 대지 아니하며 또 기름을 바르지 아니하니라',22019),
('dan-10-4','dan','다니엘',10,4,'첫째 달 이십사일에 내가 힛데겔이라 하는 큰 강 가에 있었는데',22020),
('dan-10-5','dan','다니엘',10,5,'그 때에 내가 눈을 들어 바라본즉 한 사람이 세마포 옷을 입었고 허리에는 우바스 순금 띠를 띠었더라',22021),
('dan-10-6','dan','다니엘',10,6,'또 그의 몸은 황옥 같고 그의 얼굴은 번갯빛 같고 그의 눈은 횃불 같고 그의 팔과 발은 빛난 놋과 같고 그의 말소리는 무리의 소리와 같더라',22022),
('dan-10-7','dan','다니엘',10,7,'이 환상을 나 다니엘이 홀로 보았고 나와 함께 한 사람들은 이 환상은 보지 못하였어도 그들이 크게 떨며 도망하여 숨었느니라',22023),
('dan-10-8','dan','다니엘',10,8,'그러므로 나만 홀로 있어서 이 큰 환상을 볼 때에 내 몸에 힘이 빠졌고 나의 아름다운 빛이 변하여 썩은 듯하였고 나의 힘이 다 없어졌으나',22024),
('dan-10-9','dan','다니엘',10,9,'내가 그의 음성을 들었는데 그의 음성을 들을 때에 내가 얼굴을 땅에 대고 깊이 잠들었느니라',22025),
('dan-10-10','dan','다니엘',10,10,'한 손이 있어 나를 어루만지기로 내가 떨었더니 그가 내 무릎과 손바닥이 땅에 닿게 일으키고',22026),
('dan-10-11','dan','다니엘',10,11,'내게 이르되 큰 은총을 받은 사람 다니엘아 내가 네게 이르는 말을 깨닫고 일어서라 내가 네게 보내심을 받았느니라 하더라 그가 내게 이 말을 한 후에 내가 떨며 일어서니',22027),
('dan-10-12','dan','다니엘',10,12,'그가 내게 이르되 다니엘아 두려워하지 말라 네가 깨달으려 하여 네 하나님 앞에 스스로 겸비하게 하기로 결심하던 첫날부터 네 말이 응답 받았으므로 내가 네 말로 말미암아 왔느니라',22028),
('dan-10-13','dan','다니엘',10,13,'그런데 바사 왕국의 군주가 이십일 일 동안 나를 막았으므로 내가 거기 바사 왕국의 왕들과 함께 머물러 있더니 가장 높은 군주 중 하나인 미가엘이 와서 나를 도와 주므로',22029),
('dan-10-14','dan','다니엘',10,14,'이제 내가 마지막 날에 네 백성이 당할 일을 네게 깨닫게 하러 왔노라 이는 이 환상이 오랜 후의 일임이라 하더라',22030),
('dan-10-15','dan','다니엘',10,15,'그가 이런 말로 내게 이를 때에 내가 곧 얼굴을 땅에 향하고 말문이 막혔더니',22031),
('dan-10-16','dan','다니엘',10,16,'인자와 같은 이가 있어 내 입술을 만진지라 내가 곧 입을 열어 내 앞에 서 있는 자에게 말하여 이르되 내 주여 이 환상으로 말미암아 근심이 내게 더하므로 내가 힘이 없어졌나이다',22032),
('dan-10-17','dan','다니엘',10,17,'내 몸에 힘이 없어졌고 호흡이 남지 아니하였사오니 내 주의 이 종이 어찌 능히 내 주와 더불어 말씀할 수 있으리이까 하니',22033),
('dan-10-18','dan','다니엘',10,18,'또 사람의 모양 같은 것 하나가 나를 만지며 나를 강건하게 하여',22034),
('dan-10-19','dan','다니엘',10,19,'이르되 큰 은총을 받은 사람이여 두려워하지 말라 평안하라 강건하라 강건하라 그가 이같이 내게 말하매 내가 곧 힘이 나서 이르되 내 주께서 나를 강건하게 하셨사오니 말씀하옵소서',22035),
('dan-10-20','dan','다니엘',10,20,'그가 이르되 내가 어찌하여 네게 왔는지 네가 아느냐 이제 내가 돌아가서 바사 군주와 싸우려니와 내가 나간 후에는 헬라의 군주가 이를 것이라',22036),
('dan-10-21','dan','다니엘',10,21,'오직 내가 먼저 진리의 글에 기록된 것으로 네게 보이리라 나를 도와서 그들을 대항할 자는 너희의 군주 미가엘뿐이니라',22037),
('dan-11-1','dan','다니엘',11,1,'내가 또 메대 사람 다리오 원년에 일어나 그를 도와서 그를 강하게 한 일이 있었느니라',22038),
('dan-11-2','dan','다니엘',11,2,'이제 내가 참된 것을 네게 보이리라 보라 바사에서 또 세 왕들이 일어날 것이요 그 후의 넷째는 그들보다 심히 부요할 것이며 그가 그 부요함으로 강하여진 후에는 모든 사람을 충동하여 헬라 왕국을 칠 것이며',22039),
('dan-11-3','dan','다니엘',11,3,'장차 한 능력 있는 왕이 일어나서 큰 권세로 다스리며 자기 마음대로 행하리라',22040),
('dan-11-4','dan','다니엘',11,4,'그러나 그가 강성할 때에 그의 나라가 갈라져 천하 사방에 나누일 것이나 그의 자손에게로 돌아가지도 아니할 것이요 또 자기가 주장하던 권세대로도 되지 아니하리니 이는 그 나라가 뽑혀서 그 외의 다른 사람들에게로 돌아갈 것임이라',22041),
('dan-11-5','dan','다니엘',11,5,'남방의 왕들은 강할 것이나 그 군주들 중 하나는 그보다 강하여 권세를 떨치리니 그의 권세가 심히 클 것이요',22042),
('dan-11-6','dan','다니엘',11,6,'몇 해 후에 그들이 서로 단합하리니 곧 남방 왕의 딸이 북방 왕에게 가서 화친하리라 그러나 그 공주의 힘이 쇠하고 그 왕은 서지도 못하며 권세가 없어질 뿐 아니라 그 공주와 그를 데리고 온 자와 그를 낳은 자와 그 때에 도와 주던 자가 다 버림을 당하리라',22043),
('dan-11-7','dan','다니엘',11,7,'그러나 그 공주의 본 족속에게서 난 자 중의 한 사람이 왕위를 이어 권세를 받아 북방 왕의 군대를 치러 와서 그의 성에 들어가서 그들을 쳐서 이기고',22044),
('dan-11-8','dan','다니엘',11,8,'그 신들과 부어 만든 우상들과 은과 금의 아름다운 그릇들은 다 노략하여 애굽으로 가져갈 것이요 몇 해 동안은 그가 북방 왕을 치지 아니하리라',22045),
('dan-11-9','dan','다니엘',11,9,'북방 왕이 남방 왕의 왕국으로 쳐들어갈 것이나 자기 본국으로 물러가리라',22046),
('dan-11-10','dan','다니엘',11,10,'그러나 그의 아들들이 전쟁을 준비하고 심히 많은 군대를 모아서 물이 넘침 같이 나아올 것이며 그가 또 와서 남방 왕의 견고한 성까지 칠 것이요',22047),
('dan-11-11','dan','다니엘',11,11,'남방 왕은 크게 노하여 나와서 북방 왕과 싸울 것이라 북방 왕이 큰 무리를 일으킬 것이나 그 무리는 그의 손에 넘겨 준 바 되리라',22048),
('dan-11-12','dan','다니엘',11,12,'그가 큰 무리를 사로잡은 후에 그의 마음이 스스로 높아져서 수만 명을 엎드러뜨릴 것이나 그 세력은 더하지 못할 것이요',22049),
('dan-11-13','dan','다니엘',11,13,'북방 왕은 돌아가서 다시 군대를 전보다 더 많이 준비하였다가 몇 때 곧 몇 해 후에 대군과 많은 물건을 거느리고 오리라',22050),
('dan-11-14','dan','다니엘',11,14,'그 때에 여러 사람이 일어나서 남방 왕을 칠 것이요 네 백성 중에서도 포악한 자가 스스로 높아져서 환상을 이루려 할 것이나 그들이 도리어 걸려 넘어지리라',22051),
('dan-11-15','dan','다니엘',11,15,'이에 북방 왕은 와서 토성을 쌓고 견고한 성읍을 점령할 것이요 남방 군대는 그를 당할 수 없으며 또 그가 택한 군대라도 그를 당할 힘이 없을 것이므로',22052),
('dan-11-16','dan','다니엘',11,16,'오직 와서 치는 자가 자기 마음대로 행하리니 그를 당할 사람이 없겠고 그는 영화로운 땅에 설 것이요 그의 손에는 멸망이 있으리라',22053),
('dan-11-17','dan','다니엘',11,17,'그가 결심하고 전국의 힘을 다하여 이르렀다가 그와 화친할 것이요 또 여자의 딸을 그에게 주어 그의 나라를 망하게 하려 할 것이나 이루지 못하리니 그에게 무익하리라',22054),
('dan-11-18','dan','다니엘',11,18,'그 후에 그가 그의 얼굴을 바닷가로 돌려 많이 점령할 것이나 한 장군이 나타나 그의 정복을 그치게 하고 그 수치를 그에게로 돌릴 것이므로',22055),
('dan-11-19','dan','다니엘',11,19,'그가 드디어 그 얼굴을 돌려 자기 땅 산성들로 향할 것이나 거쳐 넘어지고 다시는 보이지 아니하리라',22056),
('dan-11-20','dan','다니엘',11,20,'그 왕위를 이을 자가 압제자를 그 나라의 아름다운 곳으로 두루 다니게 할 것이나 그는 분노함이나 싸움이 없이 몇 날이 못 되어 망할 것이요',22057),
('dan-11-21','dan','다니엘',11,21,'또 그의 왕위를 이을 자는 한 비천한 사람이라 나라의 영광을 그에게 주지 아니할 것이나 그가 평안한 때를 타서 속임수로 그 나라를 얻을 것이며',22058),
('dan-11-22','dan','다니엘',11,22,'넘치는 물 같은 군대가 그에게 넘침으로 말미암아 패할 것이요 동맹한 왕도 그렇게 될 것이며',22059),
('dan-11-23','dan','다니엘',11,23,'그와 약조한 후에 그는 거짓을 행하여 올라올 것이요 소수의 백성을 가지고 세력을 얻을 것이며',22060),
('dan-11-24','dan','다니엘',11,24,'그가 평안한 때에 그 지방의 가장 기름진 곳에 들어와서 그의 조상들과 조상들의 조상이 행하지 못하던 것을 행할 것이요 그는 노략하고 탈취한 재물을 무리에게 흩어 주며 계략을 세워 얼마 동안 산성들을 칠 것인데 때가 이르기까지 그리하리라',22061),
('dan-11-25','dan','다니엘',11,25,'그가 그의 힘을 떨치며 용기를 다하여 큰 군대를 거느리고 남방 왕을 칠 것이요 남방 왕도 심히 크고 강한 군대를 거느리고 맞아 싸울 것이나 능히 당하지 못하리니 이는 그들이 계략을 세워 그를 침이니라',22062),
('dan-11-26','dan','다니엘',11,26,'그의 음식을 먹는 자들이 그를 멸하리니 그의 군대가 흩어질 것이요 많은 사람이 엎드러져 죽으리라',22063),
('dan-11-27','dan','다니엘',11,27,'이 두 왕이 마음에 서로 해하고자 하여 한 밥상에 앉았을 때에 거짓말을 할 것이라 일이 형통하지 못하리니 이는 아직 때가 이르지 아니하였으므로 그 일이 이루어지지 아니할 것임이니라',22064),
('dan-11-28','dan','다니엘',11,28,'북방 왕은 많은 재물을 가지고 본국으로 돌아가리니 그는 마음으로 언약을 거스르며 자기 마음대로 행하고 본토로 돌아갈 것이며',22065),
('dan-11-29','dan','다니엘',11,29,'작정된 기한에 그가 다시 나와서 남방에 이를 것이나 이번이 그 전번만 못하리니',22066),
('dan-11-30','dan','다니엘',11,30,'이는 깃딤의 배들이 이르러 그를 칠 것임이라 그가 낙심하고 돌아가면서 맺은 언약에 분노하였고 자기 땅에 돌아가서는 맺은 언약을 배반하는 자들을 살필 것이며',22067),
